using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using CampaignDemo;
[InitializeOnLoad]
public static class AISituationRuntimeVerification {
 static double start;static readonly List<string> checks=new List<string>();
 static AISituationRuntimeVerification(){if(SessionState.GetBool("AISituationRuntime",false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
 public static void Run(){AISituationInstaller.Run();SessionState.SetBool("AISituationRuntime",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add("PASS "+label);}
 static void Near(float a,float b,string label){Check(Mathf.Abs(a-b)<.002f,label+" actual="+a);}
 static BattleUnit Spawn(BattleWorld world,string role,Vector3 position){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/UnitLibrary/Prefabs/Enemy/"+role+"_Squad.prefab"));g.transform.position=position;var unit=g.GetComponent<BattleUnit>();unit.unitId=Guid.NewGuid().ToString("N");var mover=g.GetComponent<ArmyRoadMover>();mover.InitializeAt(world.setup.roadMap.Network,new RoadPoint(position.x,position.y),RoadRouteView.Create(g.transform,"response test",.06f,3,Color.cyan));var free=g.GetComponent<ArmyFreeMarchMover>();free.Initialize(mover.Motor);free.BindMap(world.setup.freeMarchMap);world.RegisterUnit(unit,mover);return unit;}
 static RecoveryPoint City(BattleWorld world,string id,Vector3 position,float stock){var g=new GameObject(id);g.transform.position=position;var p=g.AddComponent<RecoveryPoint>();p.pointId=id;p.ownerId="B";p.resourceStock=stock;p.transitionSeconds=.1f;p.repairFractionPerSecond=.2f;var points=new List<RecoveryPoint>(world.points){p};world.points=points.ToArray();return p;}
 static void Poll(){try{
  if(EditorApplication.timeSinceStartup-start>90)throw new Exception("AI situation timeout");if(!EditorApplication.isPlaying||Time.time<.5f)return;var world=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(world==null||!world.Initialized)return;var ai=world.GetComponent<BattleAIController>();ai.enabled=false;ai.profile=AssetDatabase.LoadAssetAtPath<AIBehaviorProfile>("Assets/Game/Data/AI/PVE_EnabledModules.asset");world.currentPlayer="A";world.fogEnabled=true;BattleUnit enemyObserver=null;
  foreach(var u in world.units){u.transform.position=u.ownerId=="A"?new Vector3(400,400):new Vector3(200,200);u.Motor?.Stop();if(u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry)enemyObserver=u;}
  Check(enemyObserver!=null,"existing player unit for observer visibility test");var troop=Spawn(world,"Infantry",Vector3.zero);var city=City(world,"response-city",Vector3.right*.2f,100);world.points=new[]{city};
  var reserve=Spawn(world,"Infantry",new Vector3(200,200));var reserveTask=ScriptableObject.CreateInstance<AITaskDefinition>();reserveTask.kind=AITaskKind.Reinforce;reserveTask.requireActivation=true;var reserveOrder=reserve.gameObject.AddComponent<AIUnitOrder>();reserveOrder.task=reserveTask;reserveOrder.taskKey="test-relief";
  var trigger=world.GetComponent<AICityReliefTrigger>();trigger.enabled=false;trigger.city=city;trigger.taskKeys=new[]{"test-relief"};trigger.threatRadius=2;trigger.requiredThreatSeconds=1;int alerts=0;trigger.onReliefCalled.AddListener(()=>alerts++);
  city.transform.position=new Vector3(1000,1000);enemyObserver.transform.position=city.transform.position+Vector3.right*.2f;trigger.Tick(5);Check(!trigger.Triggered,"hidden enemy inside city threat area cannot trigger omniscient relief");city.transform.position=Vector3.right*.2f;enemyObserver.transform.position=Vector3.right;trigger.Tick(.5f);Check(!trigger.Triggered,"visible threat must persist before relief");trigger.Tick(.6f);Check(trigger.Triggered&&alerts==1,"visible city threat activates relief and warning event");ai.Tick(.25f);Check(reserveOrder.State==AIUnitState.Holding,"reserve activation reaches existing task controller");trigger.Tick(10);Check(alerts==1,"relief triggers once");trigger.ResetTrigger();trigger.taskKeys=new[]{"missing-reserve"};trigger.Tick(2);Check(!trigger.Triggered,"missing task group does not falsely mark relief sent");enemyObserver.transform.position=new Vector3(400,400);
  var recovery=troop.gameObject.AddComponent<AIRecoveryResponse>();recovery.preferredCity=city;recovery.useRoad=false;recovery.returnToGuardPosition=false;troop.Damage(troop.Personnel*.7f);ai.Tick(.25f);Check(troop.State==ArmyBattleState.Deployed&&recovery.ResponseState.Contains("最后"),"last city guard does not abandon city to recover");recovery.keepLastCityGuard=false;ai.Tick(.25f);Check(troop.State==ArmyBattleState.Deployed,"under-fire rule blocks entry via normal command validation");world.Tick(.1f);ai.Tick(2.1f);Check(troop.State==ArmyBattleState.EnteringPoint,"low strength unit issues ordinary enter-city command");world.Tick(.2f);ai.Tick(.25f);Check(troop.State==ArmyBattleState.Repairing,"response continues while unit hidden inside city");float missing=troop.Capacity-troop.Personnel;world.Tick(4);ai.Tick(.25f);Check(troop.State==ArmyBattleState.ExitingPoint,"recovered unit exits city at configured threshold");Near(city.resourceStock,100-missing,"recovery pays actual city resources");world.Tick(.2f);ai.Tick(.25f);Check(troop.OnMap&&troop.Fraction>.9f,"recovered army returns to map and original task");
  var truck=Spawn(world,"TransportTruck",Vector3.right*.4f);var source=City(world,"supply-source",Vector3.right*.3f,80);var destination=City(world,"supply-destination",Vector3.right*.5f,0);var supply=truck.gameObject.AddComponent<AISupplyResponse>();supply.sourceCity=source;supply.destinationCity=destination;supply.loadLimit=30;supply.repeat=false;ai.Tick(.25f);Near(source.resourceStock,50,"supply loads configured partial amount");Near(destination.resourceStock,30,"supply unloads into destination via command service");Near(truck.GetComponent<TransportTruck>().Cargo,0,"cargo conserved after unload");ai.Tick(3);Near(destination.resourceStock,30,"one-trip task does not loop");
  var backup=City(world,"backup-source",Vector3.right*.3f,20);source.ownerId="A";supply.backupSourceCities=new[]{backup};supply.RestartTask();ai.Tick(.25f);Near(backup.resourceStock,0,"captured source replaced by configured owned backup");Near(source.resourceStock,50,"AI does not loot enemy source");Near(destination.resourceStock,50,"backup cargo reaches owned destination");
  source.ownerId="B";destination.ownerId="A";supply.RestartTask();ai.Tick(.25f);Near(truck.GetComponent<TransportTruck>().Cargo,30,"lost destination retains cargo instead of remote unload");Near(destination.resourceStock,50,"captured destination receives no cargo");
  var warehouseTruck=Spawn(world,"TransportTruck",Vector3.right*.4f);var warehouseSupply=warehouseTruck.gameObject.AddComponent<AISupplyResponse>();warehouseSupply.sourceDepot=world.campaign.CreateDepot(Vector3.right*.3f,"B",25,false);warehouseSupply.destinationDepot=world.campaign.CreateDepot(Vector3.right*.5f,"B",0,false);warehouseSupply.repeat=false;ai.Tick(.25f);Near(warehouseSupply.sourceDepot.stock,0,"warehouse source supported");Near(warehouseSupply.destinationDepot.stock,25,"warehouse destination supported");
  source.transform.position=Vector3.right*3;destination.ownerId="B";supply.RestartTask();enemyObserver.transform.position=truck.transform.position+Vector3.right*.1f;ai.Tick(1.1f);Check(supply.ResponseState.Contains("威胁"),"unarmed transport waits for visible threat to clear");enemyObserver.transform.position=new Vector3(400,400);source.transform.position=Vector3.right*.3f;
  var truckRecovery=truck.gameObject.AddComponent<AIRecoveryResponse>();truckRecovery.keepLastCityGuard=false;truckRecovery.preferredCity=city;truckRecovery.returnToGuardPosition=false;truck.Damage(truck.Personnel*.7f);world.Tick(.1f);float stock=source.resourceStock;ai.Tick(3);Check(truck.State==ArmyBattleState.EnteringPoint,"recovery priority overrides supply commands");Near(source.resourceStock,stock,"supply does not simultaneously transfer during recovery");
  File.WriteAllText("ai-situation-runtime-verification.txt",checks.Count+" checks passed\n"+string.Join("\n",checks));Debug.Log("AI_SITUATION_RUNTIME_VERIFIED "+checks.Count);SessionState.SetBool("AISituationRuntime",false);EditorApplication.update-=Poll;EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText("ai-situation-runtime-verification.txt",e+"\n"+string.Join("\n",checks));Debug.LogException(e);SessionState.SetBool("AISituationRuntime",false);EditorApplication.update-=Poll;EditorApplication.Exit(1);}}
}

